using System.Collections.Generic;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceActionLogic_AllCompanionsFainted", menuName = "Data/Battle/Logics/Dice Action/All Companions Fainted")]
public class DiceActionLogic_AllCompanionsFainted : DiceActionLogic
{
	[Header("Enemies")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void ActionGrabbed()
	{
		base.ActionGrabbed();
		List<GameObject> list = new List<GameObject>();
		for (int i = 0; i < currentCompanions.DecayedCompanions.Count; i++)
		{
			list.Add(currentCompanions.DecayedCompanions[i].GetComponent<CompanionInitializer>().CompanionFaintedTargetInstance.gameObject);
		}
		actionGameState.SetTargetOnActions(list);
	}
}
